const express = require('express');
const { Queue } = require('bullmq');
const Redis = require('ioredis');
const knex = require('knex')({ client: 'pg', connection: process.env.DATABASE_URL });

const app = express();
const redis = new Redis(process.env.REDIS_URL);

app.get('/api/queue-admin/:queueName/jobs/:jobId/data', async (req, res) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey) {
    return res.status(401).json({ error: 'API key required' });
  }

  // Look up organization corresponding to the API key
  const clientKey = await knex('api_credentials').where({ key: apiKey }).first();
  if (!clientKey) {
    return res.status(401).json({ error: 'Invalid API key' });
  }

  const { queueName, jobId } = req.params;
  const targetQueue = new Queue(queueName, { connection: redis });

  const job = await targetQueue.getJob(jobId);
  if (!job) {
    return res.status(404).json({ error: 'Job not found' });
  }

  // Ensure job payload matches the calling organization's ID
  if (!job.data || job.data.organizationId !== clientKey.organization_id) {
    return res.status(403).json({ error: 'Forbidden: unauthorized job access' });
  }

  res.json({
    id: job.id,
    name: job.name,
    timestamp: job.timestamp,
    payload: job.data
  });
});

app.listen(8007);
